from pathlib import Path
import re,zipfile,shutil
p=Path('public/index.html');s=p.read_text();old=next(x for x in re.findall(r'<section\b.*?</section>',s) if 'id="chapter-5"' in x)
new='''<section class="chapter" data-name="He checks the Brain. Finds rUv’s bot." id="chapter-5" aria-labelledby="s5"><div class="eyebrow">05 / The discovery that changes the plan</div><div class="layout"><div class="copy"><div class="chapter-tool">RuvNet Brain → existing poker expertise → a foundation to build on</div><h2 id="s5">“Wait.<br>rUv already<br><em>built a poker bot?”</em></h2><p class="body">RiverRoo’s next smart move is to <strong>check RuvNet Brain</strong>. Why try to invent every part of a poker player if someone in the ecosystem has already built useful pieces?<br><br>The research finds <strong>rUv’s poker-darwin trainer/solver</strong> and the <strong>local-logic poker agents</strong>. Now there is an existing poker foundation to inspect and build toward.<br><br><strong>That is the turning point:</strong> stop learning everything the hard way. Use the Brain to discover what already exists, then adapt and test the relevant pieces.</p><div class="outcome"><b>What changed</b>The discovery changes the build plan: investigate and adapt rUv’s poker work instead of designing the strategy foundation from a blank page.</div><p class="footnote">Character dialogue illustrates the discovery. We found the source; integration into RiverRoo and its effect on playing strength remain unfinished.</p></div><div class="toolscene"><div class="schematic discovery-scene"><div class="stamp">THE MOMENT THE TOOLKIT CONNECTS</div><div class="brain-question"><small>RIVERROO’S QUESTION</small>“Has rUv already built something I can learn from?”</div><div class="wire"></div><div class="toolnode"><span class="state">Research bridge</span><strong>Check RuvNet Brain</strong><small>Look for existing poker implementations and inspect their source.</small></div><div class="wire delayed"></div><div class="toolnode discovery-hit"><span class="state">Found in the ecosystem</span><strong>rUv has poker code.</strong><small>poker-darwin · metaharness<br>Poker agents · local-logic</small></div><div class="wire future"></div><div class="toolnode future"><span class="state">Next engineering step</span><strong>Build on that foundation.</strong><small>Adapt the relevant strategy pieces → integrate → test against the frozen baseline.</small></div><details class="source-detail"><summary>What did we actually find?</summary><p><a href="https://github.com/ruvnet/metaharness/tree/main/crates/poker-darwin">poker-darwin</a> supplies a poker trainer/solver and Darwin configuration search. Its Hold’em solver operates on a two-street abstraction.</p><p><a href="https://github.com/ruvnet/local-logic/tree/main/poker">local-logic</a> also contains poker agents. Discovery is verified; use as RiverRoo’s running policy is not yet demonstrated.</p><p>Grounded source: metaharness/crates/poker-darwin/README.md.</p></details></div></div></div></section>'''
s=s.replace(old,new).replace('v1.3.1','v1.3.2')
s=s.replace('RuvNet Brain</strong> led us to existing poker work.','RuvNet Brain</strong> revealed rUv’s existing poker work—and changed the plan from starting over to adapting an existing foundation.')
s=s.replace('</style>','''.brain-question{font:italic 24px/1.3 Georgia;color:#f0c17e;padding:0 4px 10px}.brain-question small{display:block;font:9px/1.4 system-ui;color:#70b4c9;letter-spacing:.14em;margin-bottom:10px}.discovery-hit{border-color:#e9ac58;background:linear-gradient(120deg,#49342099,#082338);animation:foundSource 4s ease-in-out infinite}.discovery-hit strong{color:#f3c789}.source-detail{margin-top:18px;font:12px/1.6 system-ui;color:#a5c5d5}.source-detail summary{cursor:pointer;color:#61dce6}.source-detail a{color:#f0bd78}.paused .discovery-hit{animation-play-state:paused}@keyframes foundSource{50%{box-shadow:0 0 28px #e9ac5826}}@media(prefers-reduced-motion:reduce){.discovery-hit{animation:none}}@media(max-width:760px){.brain-question{font-size:22px}} </style>''',1)
p.write_text(s)
Path('STORY-CONTRACT.md').write_text(Path('STORY-CONTRACT.md').read_text()+'\nDiscovery turning point: RiverRoo checks RuvNet Brain, discovers rUv already has poker implementations, and changes the build plan to investigate/adapt that foundation. Make this causal moment explicit through character dialogue and a visual question→Brain→found source→reuse path. Discovery is not proof of completed integration or playing-strength gain.\n')
for name in ['README.md','public/Presenter-Notes.txt']:
 f=Path(name);f.write_text(f.read_text().replace('1.3.1','1.3.2'))
with zipfile.ZipFile('public/RiverRoo-Presentation.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in Path('public').rglob('*'):
  if f.is_file() and f.suffix!='.zip' and f.name!='riverroo-character.png':z.write(f,f.relative_to('public'))
shutil.copy2('public/RiverRoo-Presentation.zip',Path.home()/'Documents/RiverRoo/RiverRoo-Presentation.zip')
Path('.receipts/story-inline.js').write_text(re.search(r'<script>(.*?)</script>',s,re.S).group(1))
print('Discovery turning point restored, v1.3.2.')
